package io.aetheris.orchestrator.trading;
import org.springframework.stereotype.Service;import java.util.*;
@Service public class AdvancedBacktestService {private final AdvancedBacktestResultRepository repo;public AdvancedBacktestService(AdvancedBacktestResultRepository repo){this.repo=repo;}public AdvancedBacktestResultEntity run(AdvancedBacktestRequest r){if(r.symbol()==null||r.symbol().isBlank()||r.bars().size()<60)throw new IllegalArgumentException("symbol and at least 60 bars are required");int fast=Math.max(2,r.fastWindow()),slow=Math.max(fast+1,r.slowWindow());if(slow>=r.bars().size()/3)throw new IllegalArgumentException("slowWindow is too large");double initial=r.initialBalance()>0?r.initialBalance():10000;int windows=Math.max(2,Math.min(r.walkForwardWindows(),8));Metrics all=simulate(r.bars(),fast,slow,initial,r);List<String>ws=new ArrayList<>();int usable=r.bars().size()-slow,span=Math.max(10,usable/windows);for(int w=0;w<windows;w++){int from=Math.max(0,slow+w*span-slow),to=w==windows-1?r.bars().size():Math.min(r.bars().size(),slow+(w+1)*span);if(to-from<=slow+2)continue;Metrics m=simulate(r.bars().subList(from,to),fast,slow,initial,r);ws.add("W"+(w+1)+"="+round(m.returnPct)+"%/DD"+round(m.maxDd)+"%");}String regime=regimes(r.bars(),fast,slow);double win=all.trades==0?0:(double)all.wins/all.trades*100;return repo.save(new AdvancedBacktestResultEntity(UUID.randomUUID(),r.symbol().trim().toUpperCase(Locale.ROOT),r.bars().size(),all.trades,all.returnPct,win,all.maxDd,all.costs,ws.size(),String.join(";",ws),regime));}public List<AdvancedBacktestResultEntity> recent(){return repo.findTop100ByOrderByCreatedAtDesc();}private Metrics simulate(List<MarketBar>b,int fast,int slow,double initial,AdvancedBacktestRequest r){double balance=initial,peak=initial,dd=0,costs=0,entry=0;int pos=0,trades=0,wins=0,held=0;double oneWay=Math.max(0,r.feeBps())+Math.max(0,r.spreadBps())/2+Math.max(0,r.slippageBps());for(int i=slow;i<b.size();i++){double f=avg(b,i-fast,i),s=avg(b,i-slow,i);int signal=f>s?1:f<s?-1:0;double price=b.get(i).close();if(pos!=0)held++;if(pos!=0&&signal!=pos){double gross=balance*((price-entry)/entry*pos);double c=balance*(oneWay/10000d)+balance*(Math.max(0,r.fundingBpsPerBar())*held/10000d);balance+=gross-c;costs+=c;trades++;if(gross-c>0)wins++;pos=0;held=0;}if(pos==0&&signal!=0){double c=balance*(oneWay/10000d);balance-=c;costs+=c;pos=signal;entry=price;held=0;}peak=Math.max(peak,balance);if(peak>0)dd=Math.max(dd,(peak-balance)/peak*100);}if(pos!=0){double price=b.getLast().close(),gross=balance*((price-entry)/entry*pos),c=balance*(oneWay/10000d)+balance*(Math.max(0,r.fundingBpsPerBar())*held/10000d);balance+=gross-c;costs+=c;trades++;if(gross-c>0)wins++;}return new Metrics((balance-initial)/initial*100,dd,trades,wins,costs);}private String regimes(List<MarketBar>b,int fast,int slow){int up=0,down=0,range=0;for(int i=slow;i<b.size();i++){double f=avg(b,i-fast,i),s=avg(b,i-slow,i),gap=Math.abs(f-s)/Math.max(1e-9,s)*100;if(gap<.15)range++;else if(f>s)up++;else down++;}return "TREND_UP="+up+",TREND_DOWN="+down+",RANGE="+range;}private double avg(List<MarketBar>b,int f,int t){double s=0;for(int i=f;i<t;i++)s+=b.get(i).close();return s/(t-f);}private double round(double v){return Math.round(v*100d)/100d;}private record Metrics(double returnPct,double maxDd,int trades,int wins,double costs){}
}
